import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { backendApi } from '../api/backend';
import CarGrid from '../components/CarGrid';
import { LoadingState, ErrorState } from '../components/admin/AdminStates';

export default function Home() {
  const navigate = useNavigate();
  const [cars, setCars] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // State สำหรับแท็บและฟอร์มค้นหา
  const [activeTab, setActiveTab] = useState('car');
  const [pickupLocation, setPickupLocation] = useState('');
  const [pickupDate, setPickupDate] = useState('');
  const [returnDate, setReturnDate] = useState('');

  useEffect(() => {
    backendApi.getCars()
      .then((data) => setCars((data || []).slice(0, 3)))
      .catch((err) => setError(err.message))
      .finally(() => setLoading(false));
  }, []);

  const handleSearch = (e) => {
    e.preventDefault();
    const params = new URLSearchParams();
    params.set('category', activeTab);
    if (pickupLocation) params.set('location', pickupLocation);
    if (pickupDate) params.set('start', pickupDate);
    if (returnDate) params.set('end', returnDate);
    navigate(`/cars?${params.toString()}`);
  };

  // สามารถนำ URL รูปภาพมาใส่ในช่อง image ได้เลย (ถ้าปล่อยว่างไว้จะแสดงกล่องสีพร้อมข้อความกำกับตามภาพ)
  const categories = [
    {
      title: 'รถเก๋ง',
      type: 'Sedan',
      desc: 'นั่งสบาย ประหยัดน้ำมัน เหมาะกับคู่รักและครอบครัวเล็ก',
      price: '800',
      bg: 'bg-[#dbe7ee]',
      label: '[รูปรถเก๋ง]',
      image: '', // ใส่ลิงก์รูปรถเก๋งตรงนี้ เช่น 'https://...' หรือ '/images/sedan.png'
    },
    {
      title: 'SUV และรถตู้',
      type: 'SUV',
      desc: 'ที่นั่งและพื้นที่เก็บของเยอะ เหมาะกับกลุ่มเพื่อนและทริปยาว',
      price: '1,500',
      bg: 'bg-[#dbe7ee]',
      label: '[รูป SUV / รถตู้]',
      image: '', // ใส่ลิงก์รูป SUV / รถตู้ตรงนี้
    },
    {
      title: 'มอเตอร์ไซค์ออโตเมติก',
      type: 'Scooter',
      desc: 'คล่องตัว ขี่ง่าย เหมาะกับเที่ยวในเมืองและเกาะ',
      price: '250',
      bg: 'bg-[#fef0c3]',
      label: '[รูปมอเตอร์ไซค์ออโตเมติก]',
      image: '', // ใส่ลิงก์รูปมอเตอร์ไซค์ออโตเมติกตรงนี้
    },
    {
      title: 'บิ๊กไบค์',
      type: 'BigBike',
      desc: 'สำหรับสายทัวร์ริ่งและผู้มีใบขับขี่ที่เหมาะสม',
      price: '1,200',
      bg: 'bg-[#fef0c3]',
      label: '[รูปบิ๊กไบค์]',
      image: '', // ใส่ลิงก์รูปบิ๊กไบค์ตรงนี้
    },
  ];

  const highlights = [
    'ราคาชัดเจน',
    'ตรวจสภาพรถก่อนรับทุกครั้ง',
    'มีประกันให้เลือก',
    'มีทีมงานคอยดูแล',
  ];

  return (
    <div className="bg-white min-h-screen text-slate-900">
      {/* 1. HERO SECTION พื้นหลังฟ้าอ่อนไล่เฉด + กล่องค้นหามีแท็บ */}
      <section className="relative overflow-hidden bg-gradient-to-b from-[#ebf3ff] to-[#f4f8ff] border-b border-blue-100 pt-14 pb-16 px-6">
        <div className="w-72 h-72 rounded-full bg-blue-200/30 absolute -top-20 -right-16 pointer-events-none"></div>
        <div className="w-64 h-64 rounded-full bg-blue-200/30 absolute -bottom-24 -left-16 pointer-events-none"></div>

        <div className="max-w-4xl mx-auto text-center relative z-10">
          <h1 className="text-3xl md:text-5xl font-bold tracking-normal text-slate-900 mb-4 leading-snug">
  ค้นหารถเช่าที่ใช่ <span className="text-[#1d64f2]">ในราคาที่คุ้ม</span>
</h1>
<p className="text-gray-600 text-sm md:text-base mb-10 tracking-normal">
  รถยนต์และมอเตอร์ไซค์ รับ-คืนได้ที่ [สถานที่รับรถ]
</p>

          {/* กล่องค้นหาสีขาวพร้อมแท็บด้านบน */}
          <div className="bg-white rounded-2xl shadow-lg shadow-blue-900/5 border border-gray-100 overflow-hidden text-left">
            <div className="flex bg-gray-50 border-b border-gray-100">
              <button
                type="button"
                onClick={() => setActiveTab('car')}
                className={`px-6 py-3.5 text-sm font-bold transition border-b-2 ${
                  activeTab === 'car'
                    ? 'bg-white text-[#1d64f2] border-[#1d64f2]'
                    : 'text-gray-500 border-transparent hover:text-gray-700'
                }`}
              >
                เช่ารถยนต์
              </button>
              <button
                type="button"
                onClick={() => setActiveTab('motorcycle')}
                className={`px-6 py-3.5 text-sm font-bold transition border-b-2 ${
                  activeTab === 'motorcycle'
                    ? 'bg-white text-[#1d64f2] border-[#1d64f2]'
                    : 'text-gray-500 border-transparent hover:text-gray-700'
                }`}
              >
                เช่ามอเตอร์ไซค์
              </button>
            </div>

            <form onSubmit={handleSearch} className="p-5 grid grid-cols-1 md:grid-cols-4 gap-4 items-end">
              <div>
                <label className="block text-xs font-semibold text-gray-500 mb-1.5">จุดรับ-คืนรถ</label>
                <input
                  type="text"
                  placeholder="เลือกสถานที่"
                  value={pickupLocation}
                  onChange={(e) => setPickupLocation(e.target.value)}
                  className="w-full border border-gray-200 rounded-xl px-3.5 py-2.5 text-sm focus:outline-none focus:border-[#1d64f2]"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-gray-500 mb-1.5">วันรับรถ</label>
                <input
                  type="date"
                  value={pickupDate}
                  onChange={(e) => setPickupDate(e.target.value)}
                  className="w-full border border-gray-200 rounded-xl px-3.5 py-2.5 text-sm focus:outline-none focus:border-[#1d64f2]"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-gray-500 mb-1.5">วันคืนรถ</label>
                <input
                  type="date"
                  value={returnDate}
                  onChange={(e) => setReturnDate(e.target.value)}
                  className="w-full border border-gray-200 rounded-xl px-3.5 py-2.5 text-sm focus:outline-none focus:border-[#1d64f2]"
                />
              </div>

              <button
                type="submit"
                className="w-full bg-[#1d64f2] text-white font-bold py-2.5 px-6 rounded-xl hover:bg-blue-700 transition text-sm h-[42px] shadow-sm"
              >
                ค้นหารถเช่า
              </button>
            </form>
          </div>

          <div className="flex flex-wrap justify-center gap-x-6 gap-y-2 mt-7 text-xs font-medium text-gray-600">
            {highlights.map((item) => (
              <div key={item} className="flex items-center space-x-1.5">
                <span className="w-4 h-4 rounded-full bg-[#1d64f2] text-white flex items-center justify-center text-[10px] font-bold">
                  ✓
                </span>
                <span>{item}</span>
              </div>
            ))}
          </div>
        </div>
      </section>

      <div className="max-w-5xl mx-auto px-6 py-14 space-y-16">
        {/* 2. เลือกตามการเดินทางของคุณ (4 การ์ดแบบใส่รูปด้านบนเต็มกรอบตามภาพ) */}
        <section>
          <div className="mb-6">
            <h2 className="text-2xl font-extrabold text-slate-900 mb-1">เลือกตามการเดินทางของคุณ</h2>
            <p className="text-sm text-gray-500">รถยนต์และมอเตอร์ไซค์ให้เลือกครบทุกแบบ</p>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-5">
            {categories.map((cat) => (
              <Link
                key={cat.title}
                to={`/cars?type=${cat.type}`}
                className="bg-white rounded-2xl overflow-hidden border border-gray-200/80 shadow-sm hover:border-[#1d64f2] hover:ring-1 hover:ring-[#1d64f2] transition flex flex-col justify-between group"
              >
                <div>
                  {/* ส่วนแสดงรูปภาพด้านบนเต็มกรอบของการ์ด */}
                  <div className={`${cat.bg} h-40 w-full overflow-hidden flex items-center justify-center`}>
                    {cat.image ? (
                      <img
                        src={cat.image}
                        alt={cat.title}
                        className="w-full h-full object-cover group-hover:scale-105 transition duration-300"
                      />
                    ) : (
                      <span className="text-xs text-slate-500 font-medium">{cat.label}</span>
                    )}
                  </div>

                  {/* เนื้อหาด้านล่างรูปภาพ */}
                  <div className="p-5">
                    <h3 className="font-bold text-base text-slate-900 mb-1.5 group-hover:text-[#1d64f2] transition">
                      {cat.title}
                    </h3>
                    <p className="text-xs text-gray-500 leading-relaxed">{cat.desc}</p>
                  </div>
                </div>

                <div className="px-5 pb-5">
                  <p className="font-extrabold text-sm text-slate-900 mb-1.5">เริ่ม ฿{cat.price} / วัน</p>
                  <span className="text-xs font-semibold text-[#1d64f2] group-hover:underline">
                    ดูรถทั้งหมด &rarr;
                  </span>
                </div>
              </Link>
            ))}
          </div>
        </section>

        {/* 3. การ์ดรูปรถจริงที่ดึงมาจาก Backend / Supabase */}
        <section>
          <div className="flex justify-between items-center mb-6">
            <div>
              <h2 className="text-2xl font-extrabold text-slate-900 mb-1">รถยอดนิยมพร้อมให้บริการ</h2>
              <p className="text-sm text-gray-500">เลือกรถที่พร้อมออกเดินทางและกดจองได้ทันที</p>
            </div>
            <Link to="/cars" className="text-sm font-semibold text-[#1d64f2] hover:underline">
              ดูรถทั้งหมด &rarr;
            </Link>
          </div>

          {loading && <LoadingState />}
          {error && <ErrorState message={error} />}
          {!loading && !error && <CarGrid cars={cars} />}
        </section>

        {/* 4. ขั้นตอนการเช่าง่ายๆ 3 ขั้นตอน */}
        <section id="steps" className="bg-gray-50 rounded-3xl p-8 md:p-10 border border-gray-100">
          <h2 className="text-2xl font-extrabold text-slate-900 mb-8">เช่าได้ใน 3 ขั้นตอน</h2>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
            <div className="border-t-2 border-[#1d64f2] pt-4">
              <div className="text-2xl font-extrabold text-[#1d64f2] mb-2">1</div>
              <h3 className="font-bold text-base mb-1">เลือกรถและวันเดินทาง</h3>
              <p className="text-xs text-gray-500">ดูรถว่างตามวันที่และสถานที่รับรถ</p>
            </div>

            <div className="border-t-2 border-[#1d64f2] pt-4">
              <div className="text-2xl font-extrabold text-[#1d64f2] mb-2">2</div>
              <h3 className="font-bold text-base mb-1">ยืนยันการจอง</h3>
              <p className="text-xs text-gray-500">กรอกข้อมูลผู้เช่าและชำระ [ค่ามัดจำ / วิธีชำระเงิน]</p>
            </div>

            <div className="border-t-2 border-[#1d64f2] pt-4">
              <div className="text-2xl font-extrabold text-[#1d64f2] mb-2">3</div>
              <h3 className="font-bold text-base mb-1">รับรถและออกเดินทาง</h3>
              <p className="text-xs text-gray-500">แสดงบัตรและใบขับขี่ ตรวจสภาพรถร่วมกัน แล้วรับกุญแจ</p>
            </div>
          </div>
        </section>

        {/* 5. เงื่อนไขการเช่า */}
        <section id="terms" className="bg-[#ebf3ff] rounded-3xl p-8 md:p-10 border border-blue-100">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
            <div>
              <h3 className="font-bold text-sm text-slate-900 mb-2">เอกสารที่ต้องใช้</h3>
              <p className="text-xs text-gray-600 leading-relaxed">
                บัตรประชาชนหรือพาสปอร์ต และใบขับขี่ที่ใช้ได้ [ระบุเงื่อนไข]
              </p>
            </div>
            <div>
              <h3 className="font-bold text-sm text-slate-900 mb-2">ประกันและค่ามัดจำ</h3>
              <p className="text-xs text-gray-600 leading-relaxed">
                [ระบุความคุ้มครองประกัน และเงื่อนไขการคืนมัดจำ]
              </p>
            </div>
            <div>
              <h3 className="font-bold text-sm text-slate-900 mb-2">การยกเลิกและเลื่อนวัน</h3>
              <p className="text-xs text-gray-600 leading-relaxed">
                [ระบุนโยบายยกเลิกการจอง]
              </p>
            </div>
          </div>
        </section>
      </div>
    </div>
  );
}
